var AN=['蚂蚁','乌龟','狐狸','乌鸦','狮子','兔子','蜜蜂','猫头鹰'];
var TR=['森林','河边','山谷','云端','洞穴','花园'];
function gen(rng){
  var a=AN[Math.floor(rng()*AN.length)], b=AN[Math.floor(rng()*AN.length)];
  while(b===a) b=AN[Math.floor(rng()*AN.length)];
  var place=TR[Math.floor(rng()*TR.length)];
  var moral=['慢即是快','骄傲使人落后','合作胜过独行','诚实最珍贵','知足常乐'][Math.floor(rng()*5)];
  return '从前，在'+place+'里住着一只'+a+'和一只'+b+'。它们性格迥异，却因一次意外成为伙伴。'
    +'历经波折后，它们明白了：'+moral+'。';
}
var EXPORTS={gen:gen};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FableForgePure = EXPORTS; }
